CREATE TABLE students (id INTEGER PRIMARY KEY, name TEXT, score INT, course_id INT);
INSERT INTO students VALUES (1,'Ada',91,1),(2,'Linus',78,1),(3,'Grace',85,2),(4,'Alan',62,2);
WITH course_avg AS (
  SELECT course_id, AVG(score) AS avg FROM students GROUP BY course_id
)
SELECT s.name, s.score, c.avg FROM students s
JOIN course_avg c ON c.course_id = s.course_id WHERE s.score > c.avg;
